#!/bin/sh
# cleanup-profiles.sh "YYYY-MM-DD HH:MM:SS" (local time): deletes the test-browser profiles and
# temp folders the QA harnesses made since then (their own prefixes only), skipping any that a
# running Chrome still uses. Prints how many it deleted. Nothing older is touched.
T=/var/folders/w5/mz126_n50kndk05nr40gmzgw0000gn/T; SINCE="$1"; [ -n "$SINCE" ] || exit 1
inuse=$(ps -axo command= | /usr/bin/grep -E "Google Chrome|Brave Browser" | /usr/bin/grep -o -- "--user-data-dir=[^ ]*" | sed 's/--user-data-dir=//' | sort -u)
n=0
for d in $(find "$T" -maxdepth 1 -type d \( -name 'a12??????' -o -name 'drawn??????' -o -name 'faults??????' -o -name 'sedit??????' -o -name 'pv??????' -o -name 'monkey??????' -o -name 'browse??????' -o -name 'safe??????' -o -name 'pkgcheck-??????' -o -name 'race??????' -o -name 'adjhold??????' -o -name 'qrd??????' -o -name 'soak??????' -o -name 'p0??????' -o -name 'drive??????' -o -name 'shot??????' -o -name 'cap??????' -o -name 'refit??????' -o -name 'lsapp??????' -o -name 'credit??????' -o -name 'setok??????' -o -name 'vischeck??????' -o -name 'consent??????' \) -newermt "$SINCE"); do
  echo "$inuse" | /usr/bin/grep -qx "$d" && continue
  case "$d" in "$T"/?*) rm -rf -- "$d" && n=$((n+1));; esac
done
echo "deleted $n test profiles made since $SINCE"
